// HasUpdates applies the HasEdge predicate on the "updates" edge.
func HasUpdates() predicate.IncidentInvestigation {
	return predicate.IncidentInvestigation(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, UpdatesTable, UpdatesColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasUpdatesWith applies the HasEdge predicate on the "updates" edge with a given conditions (other predicates).
func HasUpdatesWith(preds ...predicate.IncidentInvestigationUpdateEntry) predicate.IncidentInvestigation {
	return predicate.IncidentInvestigation(func(s *sql.Selector) {
		step := newUpdatesStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

